cd ~/devel/dotfiles/keyboards/svalboard && python3 -c "
import json
v=json.load(open('SvalHandsDownNeu.vil'))
S,E,C,N,W=0,1,2,3,4
LI,LM,LR,LP,RI,RM,RR,RP=1,2,3,4,6,7,8,9
def rd(l,h):
    rows={'left':{'pinky':LP,'ring':LR,'middle':LM,'index':LI},'right':{'pinky':RP,'ring':RR,'middle':RM,'index':RI}}[h]
    lat=E if h=='left' else W
    cols=['pinky','ring','middle','index'] if h=='left' else ['index','middle','ring','pinky']
    inner={'top':'middle','home':'index','bottom':'ring'}
    out={}
    for band,d in (('top',N),('home',C),('bottom',S)):
        r=[l[rows[f]][d] for f in cols]
        iv=l[rows[inner[band]]][lat]
        out[band]= r+[iv] if h=='left' else [iv]+r
    return out
def pretty(k):
    m={'KC_SLASH':'/','KC_DOT':'.','KC_QUOTE':\"'\",'LSFT(KC_QUOTE)':'\\\"','KC_COMMA':',','KC_SCOLON':';','KC_MINUS':'-','KC_EQUAL':'=','KC_BSLASH':'\\\\\\\\','KC_LBRACKET':'[','KC_RBRACKET':']','LSFT(KC_LBRACKET)':'{','LSFT(KC_RBRACKET)':'}','LSFT(KC_2)':'@','LSFT(KC_SCOLON)':':','LSFT(KC_EQUAL)':'+','LSFT(KC_7)':'&','LSFT(KC_MINUS)':'_','LSFT(KC_COMMA)':'<','LSFT(KC_DOT)':'>','LSFT(KC_4)':'\$','LSFT(KC_9)':'(','LSFT(KC_0)':')','LSFT(KC_8)':'*','KC_TRNS':'.'}
    return m.get(k, k[3:].lower() if k.startswith('KC_') else k)
for li,name in ((0,'LAYER 0  Hands Down Neu'),(1,'LAYER 1  Arensito symbols')):
    L=v['layout'][li]; l=rd(L,'left'); r=rd(L,'right')
    print(name)
    for band in ('top','home','bottom'):
        print('   '+' '.join(pretty(x).ljust(2) for x in l[band])+'  '+' '.join(pretty(x).ljust(2) for x in r[band]))
    print()
print('spare R pinky laterals: E=%s W=%s'%(pretty(v['layout'][0][RP][E]),pretty(v['layout'][0][RP][W])))
print('L thumb:', [pretty(x) for x in v['layout'][0][0]])
print('R thumb:', [pretty(x) for x in v['layout'][0][5]])
"
